"BEGIN { FS="\t"; OFS="\t" }
NR == 1 {
    n = NF
    for (i = 2; i <= n; i++) {
        h[i] = $i
        gsub(/[[:space:]-]/, "_", h[i])
    }
    next
}
{
    r = NR - 1
    gene[r] = $1
    for (i = 2; i <= n; i++) {
        x[r,i] = $i + 0
        total[i] += x[r,i]
    }
    R = r
}
END {
    N = n - 1
    for (i = 2; i <= n; i++)
        sorted[i] = total[i]
    for (i = 2; i <= n; i++)
        for (j = i + 1; j <= n; j++)
            if (sorted[i] > sorted[j]) {
                tmp = sorted[i]
                sorted[i] = sorted[j]
                sorted[j] = tmp
            }
    if (N % 2 == 1)
        M = sorted[2 + int(N / 2)]
    else
        M = (sorted[2 + N / 2 - 1] + sorted[2 + N / 2]) / 2
    Sreal = 10 + 0.7 * (N - 10)
    S = int(Sreal)
    if (S < Sreal)
        S++
    threshold = 10 / M * 1000000
    print "gene", h[2], h[3], h[4], h[5], h[6], h[7], h[8], h[9], h[10], h[11], h[12], h[13], h[14], h[15], h[16], h[17], h[18], h[19], h[20], h[21], h[22], h[23], h[24], h[25], h[26], h[27], h[28], h[29], h[30], h[31], h[32], h[33], h[34], h[35]
    for (r = 1; r <= R; r++) {
        pass = 0
        summed = 0
        for (i = 2; i <= n; i++) {
            summed += x[r,i]
            if (x[r,i] / total[i] * 1000000 >= threshold)
                pass++
        }
        if (pass >= S && summed >= 1000) {
            printf "%s", gene[r]
            for (i = 2; i <= n; i++)
                printf "\t%.0f", x[r,i] + 0
            printf "\n"
        }
    }
}"
